"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["76829"],{76491(e){e.exports=JSON.parse('{"id":"FIN-255","slug":"yield-to-maturity","term":"Yield to Maturity (YTM)","also_known_as":["YTM"],"difficulty":"Intermediate","definition":"Yield to maturity (YTM) is the total annual return an investor can expect from a bond if it is bought at today\'s price, held until it matures and all payments are made as promised.","explanation":["YTM combines two sources of return: the coupon payments and the gain or loss between the price paid and the face value received at maturity.","Suppose a bond with a face value of 1,000 pays 50 a year and matures in three years. If you buy it for 950, you receive 50 a year plus a 50 gain at maturity, because you get back 1,000. YTM expresses this as a single annual rate, about 6.9% here. If you paid 1,050 instead, the 50 loss at maturity would reduce the YTM below the 5% coupon rate.","Technically, YTM is the discount rate that makes the present value of all the bond\'s future payments equal to its current price. It is usually calculated with a financial calculator or spreadsheet.","YTM is the standard way to compare bonds with different prices, coupons and maturities. It assumes the issuer does not default and that coupons can be reinvested at the same rate. In reality, reinvestment rates change, so the actual return can differ. Bond prices and yields move in opposite directions: when a bond\'s price falls, its yield rises."],"note":"","total":1500,"prev":{"slug":"yield-to-call","term":"Yield to Call"},"next":{"slug":"z-score","term":"Z-Score"}}')}}]);